// === Tab: mySketch ===
let colors = ['#ED6A5A','#F4F1BB','#9BC1BC','#5D576B','#E6EBE0']

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
}

function draw() {
  background(colors[int(random(colors.length))]);
  frameRate(1);

  for (let i=0; i<100; i++) {
    myPlane();
    myPoint();
  }

    for (let i=0; i<10; i++) {
    myLine();
  }



}

function myPoint() {
  push();

  stroke(colors[int(random(colors.length))]);
  rotateX(frameCount);
  rotateY(-frameCount);
  rotateZ(frameCount);
  strokeWeight(width/100);

  point(random(-width/2,width/2),random(-height/2,height/2));
  pop();
}


function myLine() {
  push();
  rotateX(-frameCount);
  rotateY(frameCount);
  rotateZ(-frameCount);
  stroke(colors[int(random(colors.length))]);
  strokeCap(SQUARE)
  strokeWeight(width/100);

  line(random(-width/2,width/2),random(-height/2,height/2),random(-width/2,width/2),random(-height/2,height/2));
  pop();
}

function myPlane() {
  push();
  fill(colors[int(random(colors.length))]);
  noStroke();
  rotateX(frameCount);
  rotateY(frameCount);
  rotateZ(frameCount);
  translate(random(-width/2,width/2),random(-height/2,height/2))
  plane(random(width/2));
  pop();
}

function mousePressed(){
  saveCanvas('gen22_point-line-plane_' + frameCount + '.jpg')
}
